const text = html
  .replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/g, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;|&#x27;|&quot;|&amp;/g, ' ')
  .replace(/\s+/g, ' ')
  .slice(0, 3500);

const path = pageUrl.replace(/^https?:\/\/[^/]+/, '') || '/';
